-- tools/sql/0050/verify.sql  — READ-ONLY. Run after migration 0050. Every row is PASS or FAIL; all must PASS.
-- Counts marked "hosted dev" are what the 2026-10-15 development project is expected to show; another database may differ.
WITH
platform AS (SELECT 'ten_01M4ZG67WTS51Q0XN7F1Y9CCYG'::text AS id),
fn_counts AS (SELECT oid, prosecdef, provolatile, proconfig, proacl, pg_get_userbyid(proowner) AS owner, prosrc FROM pg_proc WHERE pronamespace = 'app'::regnamespace AND proname = 'platform_tenant_user_counts'),
fn_realm  AS (SELECT oid, prosecdef, provolatile FROM pg_proc WHERE pronamespace = 'app'::regnamespace AND proname = 'is_platform_realm'),
checks(sort, name, expected, actual, pass) AS (
  VALUES
  -- platform tenant, organisation, branch, roles, grants
  (10, 'platform tenant exists, type PLATFORM, ACTIVE', '1',
     (SELECT count(*)::text FROM app.tenant t, platform p WHERE t.id = p.id AND t.tenant_type = 'PLATFORM' AND t.status = 'ACTIVE'),
     (SELECT count(*) = 1 FROM app.tenant t, platform p WHERE t.id = p.id AND t.tenant_type = 'PLATFORM' AND t.status = 'ACTIVE')),
  (11, 'platform organisation and branch (code PLATFORM) exist', '1 and 1',
     (SELECT (SELECT count(*) FROM app.organisation o, platform p WHERE o.tenant_id = p.id)::text || ' and ' || (SELECT count(*) FROM app.branch b, platform p WHERE b.tenant_id = p.id AND b.code = 'PLATFORM')::text),
     (SELECT count(*) = 1 FROM app.organisation o, platform p WHERE o.tenant_id = p.id) AND (SELECT count(*) = 1 FROM app.branch b, platform p WHERE b.tenant_id = p.id AND b.code = 'PLATFORM')),
  (12, 'exactly two roles in the platform tenant', 'ROLE-PLATFORM-SUPERADMIN, ROLE-PLATFORM-SUPPORT',
     (SELECT string_agg(r.code, ', ' ORDER BY r.code) FROM app.role r, platform p WHERE r.tenant_id = p.id),
     (SELECT string_agg(r.code, ', ' ORDER BY r.code) FROM app.role r, platform p WHERE r.tenant_id = p.id) = 'ROLE-PLATFORM-SUPERADMIN, ROLE-PLATFORM-SUPPORT'),
  (13, 'SUPERADMIN holds exactly the six platform.* permissions plus audit.read', 'audit.read, platform.console, platform.flags, platform.jobs, platform.master_data, platform.release, platform.support_access',
     (SELECT string_agg(rp.permission_code, ', ' ORDER BY rp.permission_code) FROM app.role_permission rp JOIN app.role r ON r.id = rp.role_id WHERE r.code = 'ROLE-PLATFORM-SUPERADMIN'),
     (SELECT string_agg(rp.permission_code, ', ' ORDER BY rp.permission_code) FROM app.role_permission rp JOIN app.role r ON r.id = rp.role_id WHERE r.code = 'ROLE-PLATFORM-SUPERADMIN')
       = 'audit.read, platform.console, platform.flags, platform.jobs, platform.master_data, platform.release, platform.support_access'),
  (14, 'SUPPORT holds exactly platform.console and platform.support_access', 'platform.console, platform.support_access',
     (SELECT string_agg(rp.permission_code, ', ' ORDER BY rp.permission_code) FROM app.role_permission rp JOIN app.role r ON r.id = rp.role_id WHERE r.code = 'ROLE-PLATFORM-SUPPORT'),
     (SELECT string_agg(rp.permission_code, ', ' ORDER BY rp.permission_code) FROM app.role_permission rp JOIN app.role r ON r.id = rp.role_id WHERE r.code = 'ROLE-PLATFORM-SUPPORT') = 'platform.console, platform.support_access'),
  (15, 'nine grants in the platform tenant in total', '9',
     (SELECT count(*)::text FROM app.role_permission rp, platform p WHERE rp.tenant_id = p.id), (SELECT count(*) = 9 FROM app.role_permission rp, platform p WHERE rp.tenant_id = p.id)),
  (16, 'ZERO operator permissions remain on customer-tenant roles', '0',
     (SELECT count(*)::text FROM app.role_permission rp, platform p WHERE rp.tenant_id <> p.id AND rp.permission_code IN ('platform.console','platform.flags','platform.master_data','platform.jobs','platform.support_access','platform.release')),
     (SELECT count(*) = 0 FROM app.role_permission rp, platform p WHERE rp.tenant_id <> p.id AND rp.permission_code IN ('platform.console','platform.flags','platform.master_data','platform.jobs','platform.support_access','platform.release'))),
  (17, 'no platform role is held by any user yet (users are provisioned separately)', '0 before provisioning',
     (SELECT count(*)::text FROM app.user_role_assignment a JOIN app.role r ON r.id = a.role_id WHERE r.code LIKE 'ROLE-PLATFORM-%'), true),
  (18, 'data_correction.approve was NOT removed from any role (hosted dev: 5 roles: owner and admin of Alpha and Beta, admin of Demo)', '5',
     (SELECT count(*)::text FROM app.role_permission WHERE permission_code = 'data_correction.approve'),
     (SELECT count(*) = 5 FROM app.role_permission WHERE permission_code = 'data_correction.approve')),
  (19, 'data_correction.request grants unchanged (hosted dev: 9)', '9',
     (SELECT count(*)::text FROM app.role_permission WHERE permission_code = 'data_correction.request'),
     (SELECT count(*) = 9 FROM app.role_permission WHERE permission_code = 'data_correction.request')),
  -- row-level security and policies
  (20, 'RLS enabled and forced: feature_flag and master_data_item', 'master_data_item=true/true, feature_flag=true/true',
     (SELECT string_agg(relname || '=' || relrowsecurity::text || '/' || relforcerowsecurity::text, ', ' ORDER BY relname DESC) FROM pg_class WHERE relnamespace = 'app'::regnamespace AND relname IN ('feature_flag','master_data_item')),
     (SELECT bool_and(relrowsecurity AND relforcerowsecurity) AND count(*) = 2 FROM pg_class WHERE relnamespace = 'app'::regnamespace AND relname IN ('feature_flag','master_data_item'))),
  (21, 'RLS still enabled and forced: tenant, support_access_grant, data_correction_request', 'all true/true',
     (SELECT string_agg(relname || '=' || relrowsecurity::text || '/' || relforcerowsecurity::text, ', ' ORDER BY relname) FROM pg_class WHERE relnamespace = 'app'::regnamespace AND relname IN ('tenant','support_access_grant','data_correction_request')),
     (SELECT bool_and(relrowsecurity AND relforcerowsecurity) AND count(*) = 3 FROM pg_class WHERE relnamespace = 'app'::regnamespace AND relname IN ('tenant','support_access_grant','data_correction_request'))),
  (22, 'policies on tenant', 'platform_read[SELECT], tenant_self[ALL]',
     (SELECT string_agg(policyname || '[' || cmd || ']', ', ' ORDER BY policyname) FROM pg_policies WHERE schemaname = 'app' AND tablename = 'tenant'),
     (SELECT string_agg(policyname || '[' || cmd || ']', ', ' ORDER BY policyname) FROM pg_policies WHERE schemaname = 'app' AND tablename = 'tenant') = 'platform_read[SELECT], tenant_self[ALL]'),
  (23, 'policies on feature_flag', 'flag_insert[INSERT], flag_read[SELECT], flag_update[UPDATE]',
     (SELECT string_agg(policyname || '[' || cmd || ']', ', ' ORDER BY policyname) FROM pg_policies WHERE schemaname = 'app' AND tablename = 'feature_flag'),
     (SELECT string_agg(policyname || '[' || cmd || ']', ', ' ORDER BY policyname) FROM pg_policies WHERE schemaname = 'app' AND tablename = 'feature_flag') = 'flag_insert[INSERT], flag_read[SELECT], flag_update[UPDATE]'),
  (24, 'policies on master_data_item', 'master_insert[INSERT], master_read[SELECT], master_update[UPDATE]',
     (SELECT string_agg(policyname || '[' || cmd || ']', ', ' ORDER BY policyname) FROM pg_policies WHERE schemaname = 'app' AND tablename = 'master_data_item'),
     (SELECT string_agg(policyname || '[' || cmd || ']', ', ' ORDER BY policyname) FROM pg_policies WHERE schemaname = 'app' AND tablename = 'master_data_item') = 'master_insert[INSERT], master_read[SELECT], master_update[UPDATE]'),
  (25, 'policies on support_access_grant (the old tenant_isolation is gone)', 'grant_platform_request[INSERT], grant_tenant_decide[UPDATE], grant_tenant_read[SELECT]',
     (SELECT string_agg(policyname || '[' || cmd || ']', ', ' ORDER BY policyname) FROM pg_policies WHERE schemaname = 'app' AND tablename = 'support_access_grant'),
     (SELECT string_agg(policyname || '[' || cmd || ']', ', ' ORDER BY policyname) FROM pg_policies WHERE schemaname = 'app' AND tablename = 'support_access_grant') = 'grant_platform_request[INSERT], grant_tenant_decide[UPDATE], grant_tenant_read[SELECT]'),
  (26, 'policies on data_correction_request (unchanged: tenant only, no platform access)', 'tenant_isolation[ALL]',
     (SELECT string_agg(policyname || '[' || cmd || ']', ', ' ORDER BY policyname) FROM pg_policies WHERE schemaname = 'app' AND tablename = 'data_correction_request'),
     (SELECT string_agg(policyname || '[' || cmd || ']', ', ' ORDER BY policyname) FROM pg_policies WHERE schemaname = 'app' AND tablename = 'data_correction_request') = 'tenant_isolation[ALL]'),
  (27, 'a platform session cannot UPDATE support requests (no platform UPDATE policy; the only UPDATE policy is the tenant one)', '1 UPDATE policy, tenant_id = app_tenant()',
     (SELECT count(*)::text || ' UPDATE policy: ' || coalesce(max(qual), '') FROM pg_policies WHERE schemaname = 'app' AND tablename = 'support_access_grant' AND cmd = 'UPDATE'),
     (SELECT count(*) = 1 AND bool_and(qual LIKE '%tenant_id = app_tenant()%' AND qual NOT LIKE '%is_platform_realm%') FROM pg_policies WHERE schemaname = 'app' AND tablename = 'support_access_grant' AND cmd = 'UPDATE')),
  (28, 'a platform session may INSERT a support request only as PENDING and un-approved', 'with_check has is_platform_realm, PENDING, approved_by IS NULL',
     (SELECT coalesce(max(with_check), 'missing') FROM pg_policies WHERE schemaname = 'app' AND tablename = 'support_access_grant' AND policyname = 'grant_platform_request'),
     (SELECT coalesce(bool_and(with_check LIKE '%is_platform_realm%' AND with_check LIKE '%PENDING%' AND with_check LIKE '%approved_by IS NULL%'), false) FROM pg_policies WHERE schemaname = 'app' AND tablename = 'support_access_grant' AND policyname = 'grant_platform_request')),
  (29, 'flags and master data writes need the platform realm', 'insert and update checks use is_platform_realm()',
     (SELECT string_agg(policyname, ', ' ORDER BY policyname) FROM pg_policies WHERE schemaname = 'app' AND tablename IN ('feature_flag','master_data_item') AND cmd IN ('INSERT','UPDATE') AND with_check LIKE '%is_platform_realm%'),
     (SELECT count(*) = 4 FROM pg_policies WHERE schemaname = 'app' AND tablename IN ('feature_flag','master_data_item') AND cmd IN ('INSERT','UPDATE') AND with_check LIKE '%is_platform_realm%')),
  -- constraints and columns
  (30, 'tenant_type allows PLATFORM', 'definition lists PLATFORM',
     (SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid = 'app.tenant'::regclass AND conname = 'tenant_tenant_type_check'),
     (SELECT pg_get_constraintdef(oid) LIKE '%PLATFORM%' FROM pg_constraint WHERE conrelid = 'app.tenant'::regclass AND conname = 'tenant_tenant_type_check')),
  (31, 'support status check allows PENDING, ACTIVE, DENIED, REVOKED, EXPIRED', 'all five',
     (SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid = 'app.support_access_grant'::regclass AND conname = 'support_access_grant_status_check'),
     (SELECT pg_get_constraintdef(oid) LIKE '%PENDING%' AND pg_get_constraintdef(oid) LIKE '%ACTIVE%' AND pg_get_constraintdef(oid) LIKE '%DENIED%' AND pg_get_constraintdef(oid) LIKE '%REVOKED%' AND pg_get_constraintdef(oid) LIKE '%EXPIRED%' FROM pg_constraint WHERE conrelid = 'app.support_access_grant'::regclass AND conname = 'support_access_grant_status_check')),
  (32, 'four-hour window check exists and is NOT VALID (the leftover test row predates it; new and changed rows are checked)', 'present, convalidated = false',
     (SELECT 'convalidated = ' || convalidated::text FROM pg_constraint WHERE conrelid = 'app.support_access_grant'::regclass AND conname = 'support_access_grant_window_check'),
     (SELECT NOT convalidated AND pg_get_constraintdef(oid) LIKE '%04:00:00%' FROM pg_constraint WHERE conrelid = 'app.support_access_grant'::regclass AND conname = 'support_access_grant_window_check')),
  (33, 'support_access_grant has scope, incident_ref, starts_at', '3',
     (SELECT count(*)::text FROM information_schema.columns WHERE table_schema = 'app' AND table_name = 'support_access_grant' AND column_name IN ('scope','incident_ref','starts_at')),
     (SELECT count(*) = 3 FROM information_schema.columns WHERE table_schema = 'app' AND table_name = 'support_access_grant' AND column_name IN ('scope','incident_ref','starts_at'))),
  (34, 'data_correction_request has the nine API columns', '9',
     (SELECT count(*)::text FROM information_schema.columns WHERE table_schema = 'app' AND table_name = 'data_correction_request' AND column_name IN ('justification','script_ref','target_entity','change_description','dry_run_diff_key','dry_run_diff','requested_by','executed_at','executor_identity')),
     (SELECT count(*) = 9 FROM information_schema.columns WHERE table_schema = 'app' AND table_name = 'data_correction_request' AND column_name IN ('justification','script_ref','target_entity','change_description','dry_run_diff_key','dry_run_diff','requested_by','executed_at','executor_identity'))),
  (35, 'SOD-08, row-shape and five-state status checks exist on data_correction_request', '3',
     (SELECT count(*)::text FROM pg_constraint WHERE conrelid = 'app.data_correction_request'::regclass AND conname IN ('data_correction_request_sod08_check','data_correction_request_shape_check','data_correction_request_status_check') AND (conname <> 'data_correction_request_status_check' OR pg_get_constraintdef(oid) LIKE '%FAILED%')),
     (SELECT count(*) = 3 FROM pg_constraint WHERE conrelid = 'app.data_correction_request'::regclass AND conname IN ('data_correction_request_sod08_check','data_correction_request_shape_check','data_correction_request_status_check') AND (conname <> 'data_correction_request_status_check' OR pg_get_constraintdef(oid) LIKE '%FAILED%'))),
  (36, 'existing rows kept (support / correction / flags / master data; hosted dev 1 / 1 / 5 / 9, or more)', '>= 1 / 1 / 5 / 9',
     (SELECT (SELECT count(*) FROM app.support_access_grant) || ' / ' || (SELECT count(*) FROM app.data_correction_request) || ' / ' || (SELECT count(*) FROM app.feature_flag) || ' / ' || (SELECT count(*) FROM app.master_data_item)),
     (SELECT count(*) >= 1 FROM app.support_access_grant) AND (SELECT count(*) >= 1 FROM app.data_correction_request) AND (SELECT count(*) >= 5 FROM app.feature_flag) AND (SELECT count(*) >= 9 FROM app.master_data_item)),
  -- functions: owner, security, privileges
  (40, 'is_platform_realm(): STABLE, SECURITY INVOKER', 'stable, invoker',
     (SELECT CASE provolatile WHEN 's' THEN 'stable' ELSE provolatile::text END || ', ' || CASE WHEN prosecdef THEN 'definer' ELSE 'invoker' END FROM fn_realm),
     (SELECT provolatile = 's' AND NOT prosecdef FROM fn_realm)),
  (41, 'platform_tenant_user_counts(): SECURITY DEFINER with a fixed search_path', 'definer, search_path=app, pg_temp',
     (SELECT CASE WHEN prosecdef THEN 'definer' ELSE 'invoker' END || ', ' || coalesce(array_to_string(proconfig, ';'), 'no config') FROM fn_counts),
     (SELECT prosecdef AND array_to_string(proconfig, ';') LIKE '%search_path=app, pg_temp%' FROM fn_counts)),
  (42, 'platform_tenant_user_counts() owner can see all rows (so the aggregate counts past tenant policies)', 'owner bypasses RLS',
     (SELECT owner || ' bypassrls=' || (SELECT rolbypassrls::text FROM pg_roles WHERE rolname = fn_counts.owner) FROM fn_counts),
     (SELECT rolbypassrls OR rolsuper FROM pg_roles WHERE rolname = (SELECT owner FROM fn_counts))),
  (43, 'platform_tenant_user_counts() refuses outside the platform realm (guard is in the function body)', 'body calls is_platform_realm() and raises 42501',
     (SELECT CASE WHEN prosrc LIKE '%is_platform_realm%' AND prosrc LIKE '%42501%' THEN 'guard present' ELSE 'guard MISSING' END FROM fn_counts),
     (SELECT prosrc LIKE '%NOT is_platform_realm()%' AND prosrc LIKE '%42501%' FROM fn_counts)),
  (44, 'EXECUTE on platform_tenant_user_counts(): dsa_app yes; PUBLIC, anon, authenticated, service_role no', 'dsa_app only',
     (SELECT (SELECT 'dsa_app=' || has_function_privilege('dsa_app', fn_counts.oid, 'EXECUTE')::text FROM fn_counts) || ', public=' ||
             coalesce((SELECT (EXISTS (SELECT 1 FROM aclexplode(fn_counts.proacl) a WHERE a.grantee = 0))::text FROM fn_counts), 'true (no ACL = default PUBLIC)') || ', ' ||
             coalesce((SELECT string_agg(rolname || '=' || has_function_privilege(rolname, fn_counts.oid, 'EXECUTE')::text, ', ' ORDER BY rolname) FROM pg_roles, fn_counts WHERE rolname IN ('anon','authenticated','service_role')), 'no api roles')),
     (SELECT has_function_privilege('dsa_app', oid, 'EXECUTE') AND proacl IS NOT NULL AND NOT EXISTS (SELECT 1 FROM aclexplode(proacl) a WHERE a.grantee = 0)
             AND NOT EXISTS (SELECT 1 FROM pg_roles r WHERE r.rolname IN ('anon','authenticated','service_role') AND has_function_privilege(r.rolname, oid, 'EXECUTE')) FROM fn_counts))
)
SELECT name, expected, actual, CASE WHEN pass THEN 'PASS' ELSE 'FAIL' END AS result FROM checks ORDER BY sort;
